    "initials": "AA",
    "description": "I'm Ali - doctor turned entrepreneur, YouTuber, and author of the New York Times bestseller Feel-Good Productivity. On this channel, we explore the skills that school didn't teach you - productivity, personal development, how to become financially free, how to build your own independent business. These are the skills I learned through trial-and-error while trying to build my own business alongside medical school at Cambridge University. After years of trying, learning and making mistakes, I ended up in a life I could never have imagined. On this YouTube channel, I try my best to share everything I've learned (and that I'm continuing to learn) along the way :) The channel's been active since 2017, when I first started vlogging my life as a medical student and sharing study tips. Since then, I graduated, became a doctor, worked full-time in the UK's NHS (including during COVID), started a business, grew it to 7-figures, wrote a book, got married and had a baby girl :)",
