    "initials": "LL",
    "description": "Hello, everybody. This channel is dedicated to my greatest passion -- languages. My name is Luca and I'm from Italy. I've been studying languages for about 20 years and a few years ago I reached a very important conclusion: languages cannot be taught; they can only be learned. Once you realize that it totally changes your approach and you understand why the famous \"language classes\" have such a low success rate. So I decided to share not only my passion for languages but also techniques for studying them, with optimism, passion, effective methods and experience. Learning a new language takes time but it's not difficult. My mission is to help people understand that. If anyone tells you you that just knowing English is enough tell him \"he who learns another language acquires another soul\". Luca Lampariello [language coach]",
