    "description": "In today's world we live connected to what happens in corners far from our reality. Many times we feel the impact of some events that happen thousand of kilometers away and it seems they are part of our daily life. However, in the middle of the 21st century, the planet Earth remains vast for each of us. We are interested in knowing how the current world works and transmit it through small stories. In the middle of so many news that arise every day, we want to look beyond and find the most incredible singularities that live with us. ✉️ hola@unmundoinmenso.com",
