    "description": "Today is a perfect day to learn some Ukrainian! My name is Olya, thank you for clicking and now let me teach you some Ukrainian. I have always been a language enthusiast: I've learned English by myself, I made an attempt at learning Arabic (which I hope to get back to in the future), I am now learning German. But of course, of course I feel the most passionate about my mother tongue Ukrainian and helping those who are interested in learning it. I have been posting my videos for about 10 years now. It is one of the most important projects of my life and I am thankful to everyone who is a part of it - your likes, comments and subscriptions mean a lot to me! Sooo, if you're interested, I encourage you to stay with me and I hope we will have fun learning together!",
